using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.LocalDold;

internal sealed class PeriodicRepairDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Exact zero and half-residue repairs", H("Exact zero and half-residue repairs"), Blocks(
            Paragraph(Text("The periodic integer samples are actual functions of the index. The baseline and spike transforms are proved by Mobius inversion; exact divisor classification identifies the least positive Dold multiplier, while explicit finite permutations supply all positive-time fixed counts. The complete local-block-to-affine-sample valuation bridge is still required. The scalar unit-mismatch necessity follows the earlier Ma-Zhang method; the exact multipliers and signed orbit conclusions follow the supplied revised manuscript. The general scalar sufficiency/repair bound outside these residue families remains open. Registration is unfinished under issue 29392.")),
            Describe.Lean(DescribeId.Create("periodicrepair-zero-transform"),
                DeclarationHandle.Create("D5/S3/Arith/LocalDold/PeriodicRepair.zero_transform"),
                H("zero_transform"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Scale/jaidee2026blockdold")),
                Blocks(Paragraph(Text("For R>0, any integer C and n>0, the transform of 1+C times the indicator R divides n equals the unit-index baseline plus C at index R. At R=1 both contributions are added, rather than treated as distinct indices."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("periodicrepair-zero-dold-iff"),
                DeclarationHandle.Create("D5/S3/Arith/LocalDold/PeriodicRepair.zero_dold_iff"),
                H("zero_dold_iff"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Scale/jaidee2026blockdold")),
                Blocks(Paragraph(Text("For R>0 and natural C,c, c times the zero-residue sample is Dold exactly when R divides c*C. The statement includes C=0 and c=0; almost-Dold use requires c>0."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("periodicrepair-half-transform"),
                DeclarationHandle.Create("D5/S3/Arith/LocalDold/PeriodicRepair.half_transform"),
                H("half_transform"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Scale/jaidee2026blockdold")),
                Blocks(Paragraph(Text("For D>0, any integer C and n>0, the transform of the half sample equals the baseline at one plus C at D minus C at 2D. The half sample is first defined by the difference of its two divisibility indicators; half_residue proves its exact residue correspondence."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("periodicrepair-half-negative"),
                DeclarationHandle.Create("D5/S3/Arith/LocalDold/PeriodicRepair.half_negative"),
                H("half_negative"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Scale/jaidee2026blockdold")),
                Blocks(Paragraph(Text("For D,C,c positive, the transform of c times the half sample at 2D is strictly negative. A positive multiplier preserves the negative orbit obstruction; no positivity conclusion is inferred from Dold divisibility."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("periodicrepair-zero-repair-iff"),
                DeclarationHandle.Create("D5/S3/Arith/LocalDold/PeriodicRepair.zero_repair_iff"),
                H("zero_repair_iff"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Scale/jaidee2026blockdold")),
                Blocks(Paragraph(Text("For R>0 and natural C,c, the zero-residue sample multiplied by c is Dold if and only if R/gcd(R,C) divides c. The divisor is positive, is itself a repair and divides every positive repair, giving the least multiplier. In the manuscript C=P-1."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("periodicrepair-half-repair-iff"),
                DeclarationHandle.Create("D5/S3/Arith/LocalDold/PeriodicRepair.half_repair_iff"),
                H("half_repair_iff"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Scale/jaidee2026blockdold")),
                Blocks(Paragraph(Text("For D>0 and natural C,c, the half-residue sample multiplied by c is Dold if and only if 2D/gcd(2D,C) divides c. Its Dold repair remains finite despite its negative orbit quotient."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("periodicrepair-zero-finite-model"),
                DeclarationHandle.Create("D5/S3/Arith/LocalDold/PeriodicRepair.zero_finite_model"),
                H("zero_finite_model"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Scale/jaidee2026blockdold")),
                Blocks(Paragraph(Text("If R>0 and R divides M*C, there is one actual finite carrier and rotation whose fixed-point count at every positive n is M times the zero-residue sample. It has M fixed points and M*C/R cycles of length R, combining at R=1."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("periodicrepair-half-finite-signed-model"),
                DeclarationHandle.Create("D5/S3/Arith/LocalDold/PeriodicRepair.half_finite_signed_model"),
                H("half_finite_signed_model"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Scale/jaidee2026blockdold")),
                Blocks(Paragraph(Text("If D>0 and 2D divides M*C, two actual finite carriers and permutations have fixed-count difference M times the half sample at every positive n. The plus model has M fixed points and M*C/D cycles of length D; the minus model has M*C/(2D) cycles of length 2D."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("periodicrepair-half-residue"),
                DeclarationHandle.Create("D5/S3/Arith/LocalDold/PeriodicRepair.half_residue"),
                H("half_residue"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Scale/jaidee2026blockdold")),
                Blocks(Paragraph(Text("For D>0 and every integer C and natural n, the signed indicator definition of the half sample is exactly 1+C times the indicator n modulo 2D equals D."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("periodicrepair-periodic-unit-invariance"),
                DeclarationHandle.Create("D5/S3/Arith/LocalDold/PeriodicRepair.periodic_unit_invariance"),
                H("periodic_unit_invariance"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Scale/jaidee2026blockdold")),
                Blocks(Paragraph(Text("For any periodic integer sequence u of positive period R, a positive integer c satisfying all Dold congruences for c*u forces u(m*r)=u(m) for every positive m,r with r coprime to R. Dirichlet provides arbitrarily large primes in the fixed unit class; a nonzero fixed integer difference cannot be divisible by those primes. This is a scalar necessity theorem, not the withdrawn vector assertion."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("periodicrepair-residue-repair-necessary"),
                DeclarationHandle.Create("D5/S3/Arith/LocalDold/PeriodicRepair.residue_repair_necessary"),
                H("residue_repair_necessary"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Scale/jaidee2026blockdold")),
                Blocks(Paragraph(Text("For R>0, 0<=z<R and C,c positive, Dold divisibility for c times 1+C times the single residue indicator modulo R implies R divides 2z. The minus-one unit yields precisely the zero-or-half restriction. No assumption of this desired conclusion is placed in the hypotheses."))), DescribeRole.Theorem))));
}
